            value >>= 4;
        }
        require(value == 0, "Strings: hex length insufficient");
        return string(buffer);
    }

    /**
     * @dev Converts an `address` with fixed length of 20 bytes to its not checksummed ASCII `string` hexadecimal representation.
     */
    function toHexString(address addr) internal pure returns (string memory) {
        return toHexString(uint256(uint160(addr)), _ADDRESS_LENGTH);
    }

    /**
     * @dev Returns true if the two strings are equal.
     */
    function equal(string memory a, string memory b) internal pure returns (bool) {
        return keccak256(bytes(a)) == keccak256(bytes(b));
    }
}

contracts/AuditProof.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/cryptography/EIP712.sol";

/**
 * @title AuditProof
 * @dev 结果审计与托管释放合约
 * 
 * 实现"任务完成"的链上验证：
 * 1. 托管资金：用户预存资金到合约
 * 2. 任务绑定：关联 proofHash（预期结果哈希）
 * 3. 验证释放：Auditor 或用户确认结果后释放资金
 * 
 * 支持三种验证模式：
 * - SIGNATURE: 指定 Auditor 签名验证
 * - HASH_MATCH: 结果哈希匹配验证
 * - MULTISIG: 多签验证（M-of-N）
 */
contract AuditProof is Ownable, ReentrancyGuard, Pausable, EIP712 {
    using SafeERC20 for IERC20;
    using ECDSA for bytes32;

    // ============ 常量 ============
    bytes32 public constant RELEASE_TYPEHASH = keccak256(
        "Release(bytes32 taskId,bytes32 resultHash,uint256 quality,uint256 nonce)"
    );
    
    uint256 public constant MAX_AUDITORS = 10;
    uint256 public constant MIN_QUALITY_SCORE = 60; // 最低质量分（0-100）
    uint256 public constant DISPUTE_WINDOW = 24 hours; // 争议窗口期

    // ============ 枚举 ============
    enum VerificationMode {
        SIGNATURE,      // 签名验证
        HASH_MATCH,     // 哈希匹配
        MULTISIG        // 多签验证
    }

    enum TaskStatus {
        CREATED,        // 已创建
        FUNDED,         // 已托管资金
        SUBMITTED,      // 已提交结果
        VERIFIED,       // 已验证
        RELEASED,       // 已释放资金
        DISPUTED,       // 争议中
        REFUNDED        // 已退款
    }

    // ============ 结构体 ============
    
    /**
     * @dev 任务配置 - 简化版本避免 Stack too deep
     */
    struct TaskConfig {
        bytes32 taskId;              // 任务 ID
        address creator;             // 任务创建者（付款方）
        address executor;            // 执行者（收款方）
        
        // 资金信息
        address token;               // 支付代币
        uint256 amount;              // 托管金额
        uint256 platformFee;         // 平台费用
        
        // 验证配置
        VerificationMode mode;       // 验证模式
        bytes32 expectedProofHash;   // 预期结果哈希（用于 HASH_MATCH 模式）
        uint256 requiredSignatures;  // 所需签名数（用于 MULTISIG 模式）
        
        // 状态
        TaskStatus status;
        uint256 createdAt;
        uint256 deadline;            // 任务截止时间
        uint256 releasedAt;
        
        // 结果
        bytes32 submittedResultHash; // 提交的结果哈希
        uint256 qualityScore;        // 质量评分 (0-100)
    }

    /**
     * @dev 签名记录
     */
    struct SignatureRecord {
        address signer;
        bytes32 resultHash;
        uint256 quality;
        uint256 timestamp;
    }

    // ============ 状态变量 ============
    
    mapping(bytes32 => TaskConfig) public tasks;
    mapping(bytes32 => address[]) public taskAuditors;  // 分离存储审计员列表
    mapping(bytes32 => SignatureRecord[]) public taskSignatures;
    mapping(bytes32 => mapping(address => bool)) public hasSignedTask;
    mapping(address => bool) public trustedAuditors;
    
    // 平台配置
    address public platformTreasury;
    uint256 public defaultPlatformFeeRate = 100; // 1% = 100 basis points
    uint256 public nonce;

    // ============ 事件 ============
    
    event TaskCreated(
        bytes32 indexed taskId,
        address indexed creator,
        address indexed executor,
        uint256 amount,
        VerificationMode mode
    );
    
    event TaskFunded(
        bytes32 indexed taskId,
        address indexed funder,
        uint256 amount
    );
    
    event ResultSubmitted(
        bytes32 indexed taskId,
        address indexed executor,
        bytes32 resultHash
    );
    
    event ProofVerified(
        bytes32 indexed taskId,
        address indexed auditor,
        bytes32 resultHash,
        uint256 quality
    );
    
    event FundsReleased(
        bytes32 indexed taskId,
        address indexed executor,
        uint256 amount,
        uint256 platformFee
    );
    
    event TaskDisputed(
        bytes32 indexed taskId,
        address indexed disputer,
        string reason
    );
    
    event TaskRefunded(
        bytes32 indexed taskId,
        address indexed creator,
        uint256 amount
    );

    event AuditorUpdated(address indexed auditor, bool trusted);

    // ============ 构造函数 ============
    
    constructor(address _treasury) EIP712("AuditProof", "1") {
        platformTreasury = _treasury;
    }

    // ============ 管理函数 ============

    function setTrustedAuditor(address auditor, bool trusted) external onlyOwner {
        trustedAuditors[auditor] = trusted;
        emit AuditorUpdated(auditor, trusted);
    }

    function setPlatformTreasury(address treasury) external onlyOwner {
        require(treasury != address(0), "Invalid treasury");
        platformTreasury = treasury;
    }

    function setDefaultPlatformFeeRate(uint256 rate) external onlyOwner {
        require(rate <= 1000, "Fee rate too high"); // Max 10%
        defaultPlatformFeeRate = rate;
    }

    // ============ 核心函数 ============

    /**
     * @dev 创建托管任务
     */
    function createTask(
        bytes32 taskId,
        address executor,
        address token,
        uint256 amount,
        VerificationMode mode,
        bytes32 expectedProofHash,
        address[] calldata auditors,
        uint256 requiredSignatures,
        uint256 deadline
    ) external whenNotPaused returns (bytes32) {
        require(tasks[taskId].taskId == bytes32(0), "Task exists");
        require(executor != address(0), "Invalid executor");
        require(amount > 0, "Invalid amount");
        require(deadline > block.timestamp, "Invalid deadline");
        
        // 验证模式特定检查
        if (mode == VerificationMode.HASH_MATCH) {
            require(expectedProofHash != bytes32(0), "Hash required");
        } else if (mode == VerificationMode.SIGNATURE) {
            require(auditors.length > 0 && auditors.length <= MAX_AUDITORS, "Invalid auditors");
        } else if (mode == VerificationMode.MULTISIG) {
            require(auditors.length >= requiredSignatures, "Invalid multisig config");
            require(requiredSignatures > 0, "Need at least 1 signature");
        }

        uint256 platformFee = (amount * defaultPlatformFeeRate) / 10000;

        TaskConfig storage task = tasks[taskId];
        task.taskId = taskId;
        task.creator = msg.sender;
        task.executor = executor;
        task.token = token;
        task.amount = amount;
        task.platformFee = platformFee;
        task.mode = mode;
        task.expectedProofHash = expectedProofHash;
        task.requiredSignatures = requiredSignatures;
        task.status = TaskStatus.CREATED;
        task.createdAt = block.timestamp;
        task.deadline = deadline;
        
        // 分离存储审计员列表
        for (uint i = 0; i < auditors.length; i++) {
            taskAuditors[taskId].push(auditors[i]);
        }

        emit TaskCreated(taskId, msg.sender, executor, amount, mode);
        return taskId;
    }

    /**
     * @dev 为任务注资（托管）
     */
    function fundTask(bytes32 taskId) external payable whenNotPaused nonReentrant {
        TaskConfig storage task = tasks[taskId];
        require(task.taskId != bytes32(0), "Task not found");
        require(task.status == TaskStatus.CREATED, "Invalid status");
        
        uint256 totalRequired = task.amount + task.platformFee;
        
        if (task.token == address(0)) {
            // ETH 支付
            require(msg.value >= totalRequired, "Insufficient ETH");
            // 退还多余的 ETH
            if (msg.value > totalRequired) {
                (bool refundSuccess, ) = payable(msg.sender).call{value: msg.value - totalRequired}("");
                require(refundSuccess, "ETH refund failed");
            }
        } else {
            // ERC20 支付
            IERC20(task.token).safeTransferFrom(msg.sender, address(this), totalRequired);
        }

        task.status = TaskStatus.FUNDED;
        emit TaskFunded(taskId, msg.sender, totalRequired);
    }

    /**
     * @dev 提交任务结果（执行者调用）
     */
    function submitResult(
        bytes32 taskId,
        bytes32 resultHash
    ) external whenNotPaused nonReentrant {
        TaskConfig storage task = tasks[taskId];
        require(task.taskId != bytes32(0), "Task not found");
        require(task.status == TaskStatus.FUNDED, "Task not funded");
        require(msg.sender == task.executor, "Not executor");
        require(block.timestamp <= task.deadline, "Task expired");

        task.submittedResultHash = resultHash;
        task.status = TaskStatus.SUBMITTED;

        emit ResultSubmitted(taskId, msg.sender, resultHash);

        // 如果是哈希匹配模式，自动验证
        if (task.mode == VerificationMode.HASH_MATCH) {
            if (resultHash == task.expectedProofHash) {
                _verifyAndRelease(taskId, 100); // 完全匹配给 100 分
            }
        }
    }

    /**
     * @dev 审计员验证结果
     */
    function verifyResult(
        bytes32 taskId,
        bytes32 resultHash,
        uint256 quality,
        bytes calldata signature
    ) external whenNotPaused nonReentrant {
        TaskConfig storage task = tasks[taskId];
        require(task.taskId != bytes32(0), "Task not found");
        require(task.status == TaskStatus.SUBMITTED, "Not submitted");
        require(!hasSignedTask[taskId][msg.sender], "Already signed");
        require(quality <= 100, "Invalid quality");

        // 验证签名
        bytes32 structHash = keccak256(abi.encode(
            RELEASE_TYPEHASH,
            taskId,
            resultHash,
            quality,
            nonce++
        ));
        bytes32 digest = _hashTypedDataV4(structHash);
        address signer = digest.recover(signature);

        // 检查签名者权限
        bool isValidSigner = false;
        address[] storage auditors = taskAuditors[taskId];
        if (task.mode == VerificationMode.SIGNATURE || task.mode == VerificationMode.MULTISIG) {
            for (uint i = 0; i < auditors.length; i++) {
                if (auditors[i] == signer) {
                    isValidSigner = true;
                    break;
                }
            }
        }
        // 也允许受信任的全局审计员
        if (trustedAuditors[signer]) {
            isValidSigner = true;
        }
        require(isValidSigner, "Invalid signer");

        // 记录签名
        hasSignedTask[taskId][signer] = true;
        taskSignatures[taskId].push(SignatureRecord({
            signer: signer,
            resultHash: resultHash,
            quality: quality,
            timestamp: block.timestamp
        }));

        emit ProofVerified(taskId, signer, resultHash, quality);

        // 检查是否达到释放条件
        if (task.mode == VerificationMode.SIGNATURE) {
            // 单签名模式：任意一个审计员签名即可
            if (quality >= MIN_QUALITY_SCORE) {
                _verifyAndRelease(taskId, quality);
            }
        } else if (task.mode == VerificationMode.MULTISIG) {
            // 多签模式：需要足够数量的签名
            if (taskSignatures[taskId].length >= task.requiredSignatures) {
                // 计算平均质量分
                uint256 totalQuality = 0;
                for (uint i = 0; i < taskSignatures[taskId].length; i++) {
                    totalQuality += taskSignatures[taskId][i].quality;
                }
                uint256 avgQuality = totalQuality / taskSignatures[taskId].length;
                if (avgQuality >= MIN_QUALITY_SCORE) {
                    _verifyAndRelease(taskId, avgQuality);
                }
            }
        }
    }

    /**
     * @dev 用户直接确认释放（创建者调用）
     */
    function confirmRelease(bytes32 taskId, uint256 quality) external whenNotPaused nonReentrant {
        TaskConfig storage task = tasks[taskId];
        require(task.taskId != bytes32(0), "Task not found");
        require(msg.sender == task.creator, "Not creator");
        require(task.status == TaskStatus.SUBMITTED || task.status == TaskStatus.FUNDED, "Invalid status");

        _verifyAndRelease(taskId, quality);
    }

    /**
     * @dev 发起争议
     */
    function disputeTask(bytes32 taskId, string calldata reason) external whenNotPaused {
        TaskConfig storage task = tasks[taskId];
        require(task.taskId != bytes32(0), "Task not found");
        require(msg.sender == task.creator || msg.sender == task.executor, "Not participant");
        require(
            task.status == TaskStatus.SUBMITTED || task.status == TaskStatus.VERIFIED,
            "Cannot dispute"
        );

        task.status = TaskStatus.DISPUTED;
        emit TaskDisputed(taskId, msg.sender, reason);
    }

    /**
     * @dev 解决争议（仅 Owner）
     */
    function resolveDispute(
        bytes32 taskId,
        bool releaseToExecutor,
        uint256 executorShare // basis points
    ) external onlyOwner nonReentrant {
        TaskConfig storage task = tasks[taskId];
        require(task.status == TaskStatus.DISPUTED, "Not disputed");
        require(executorShare <= 10000, "Invalid share");

        if (releaseToExecutor) {
            uint256 executorAmount = (task.amount * executorShare) / 10000;
            uint256 creatorRefund = task.amount - executorAmount;

            if (task.token == address(0)) {
                if (executorAmount > 0) {
                    (bool s1, ) = payable(task.executor).call{value: executorAmount}("");
                    require(s1, "ETH transfer failed");
                }
                if (creatorRefund > 0) {
                    (bool s2, ) = payable(task.creator).call{value: creatorRefund}("");
                    require(s2, "ETH transfer failed");
                }
                (bool s3, ) = payable(platformTreasury).call{value: task.platformFee}("");
                require(s3, "ETH transfer failed");
            } else {
                if (executorAmount > 0) IERC20(task.token).safeTransfer(task.executor, executorAmount);
                if (creatorRefund > 0) IERC20(task.token).safeTransfer(task.creator, creatorRefund);
                IERC20(task.token).safeTransfer(platformTreasury, task.platformFee);
            }
        } else {
            // 全额退款给创建者
            uint256 refund = task.amount + task.platformFee;
            if (task.token == address(0)) {
                (bool s4, ) = payable(task.creator).call{value: refund}("");
                require(s4, "ETH transfer failed");
            } else {
                IERC20(task.token).safeTransfer(task.creator, refund);
            }
        }

        task.status = TaskStatus.RELEASED;
    }

    /**
     * @dev 过期退款
     */
    function refundExpired(bytes32 taskId) external whenNotPaused nonReentrant {
        TaskConfig storage task = tasks[taskId];
        require(task.taskId != bytes32(0), "Task not found");
        require(msg.sender == task.creator, "Not creator");
        require(block.timestamp > task.deadline + DISPUTE_WINDOW, "Not expired");
        require(
            task.status == TaskStatus.FUNDED || task.status == TaskStatus.SUBMITTED,
            "Cannot refund"
        );

        uint256 refund = task.amount + task.platformFee;
        task.status = TaskStatus.REFUNDED;

        if (task.token == address(0)) {
            (bool success, ) = payable(task.creator).call{value: refund}("");
            require(success, "ETH transfer failed");
        } else {
            IERC20(task.token).safeTransfer(task.creator, refund);
        }

        emit TaskRefunded(taskId, task.creator, refund);
    }

    // ============ 内部函数 ============

    function _verifyAndRelease(bytes32 taskId, uint256 quality) internal {
        TaskConfig storage task = tasks[taskId];
        require(task.status != TaskStatus.RELEASED, "Already released");
        require(task.status != TaskStatus.REFUNDED, "Already refunded");

        task.status = TaskStatus.VERIFIED;
        task.qualityScore = quality;

        // 分发资金
        if (task.token == address(0)) {
            // ETH - 使用 call 替代 transfer
            (bool s1, ) = payable(task.executor).call{value: task.amount}("");
            require(s1, "ETH transfer failed");
            (bool s2, ) = payable(platformTreasury).call{value: task.platformFee}("");
            require(s2, "ETH transfer failed");
        } else {
            // ERC20
            IERC20(task.token).safeTransfer(task.executor, task.amount);
            IERC20(task.token).safeTransfer(platformTreasury, task.platformFee);
        }

        task.status = TaskStatus.RELEASED;
        task.releasedAt = block.timestamp;

        emit FundsReleased(taskId, task.executor, task.amount, task.platformFee);
    }

    // ============ 视图函数 ============

    function getTask(bytes32 taskId) external view returns (TaskConfig memory) {
        return tasks[taskId];
    }

    function getTaskSignatures(bytes32 taskId) external view returns (SignatureRecord[] memory) {
        return taskSignatures[taskId];
    }

    function isAuditorForTask(bytes32 taskId, address auditor) external view returns (bool) {
        address[] storage auditors = taskAuditors[taskId];
        for (uint i = 0; i < auditors.length; i++) {
            if (auditors[i] == auditor) return true;
        }
        return trustedAuditors[auditor];
    }

    function getTaskAuditors(bytes32 taskId) external view returns (address[] memory) {
        return taskAuditors[taskId];
    }

    // ============ 紧急函数 ============

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    function emergencyWithdraw(address token, uint256 amount) external onlyOwner {
        if (token == address(0)) {
            (bool success, ) = payable(owner()).call{value: amount}("");
            require(success, "ETH transfer failed");
        } else {
            IERC20(token).safeTransfer(owner(), amount);
        }
    }

    // 允许合约接收 ETH
    receive() external payable {}
}

contracts/AutoPay.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/**
 * @title AutoPay
 * @dev 自动支付合约，管理用户对Agent的自动支付授权
 * @notice 支持 ERC20 代币的自动支付授权和执行
 */
contract AutoPay is Ownable, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    // 支付代币
    IERC20 public paymentToken;
    // 授权结构
    struct Grant {
        address user;
        address agent;
        uint256 singleLimit; // 单次限额
        uint256 dailyLimit; // 每日限额
        uint256 usedToday; // 今日已用
        uint256 lastResetDate; // 上次重置日期
        uint256 expiresAt; // 过期时间
        bool isActive;
    }

    // 支付记录
    struct AutoPayment {
        bytes32 paymentId;
        address user;
        address agent;
        address recipient;
        uint256 amount;
        uint256 timestamp;
        bool executed;
    }

    // 事件
    event GrantCreated(
        address indexed user,
        address indexed agent,
        uint256 singleLimit,
        uint256 dailyLimit,
        uint256 expiresAt
    );

    event GrantRevoked(address indexed user, address indexed agent);

    event AutoPaymentExecuted(
        bytes32 indexed paymentId,
        address indexed user,
        address indexed agent,
        address recipient,
        uint256 amount
    );

    // 状态变量
    mapping(address => mapping(address => Grant)) public grants;
    mapping(bytes32 => AutoPayment) public autoPayments;

    /**
     * @dev 创建自动支付授权
     * @param agent Agent地址
     * @param singleLimit 单次限额
     * @param dailyLimit 每日限额
     * @param duration 授权时长（秒）
     */
    function createGrant(
        address agent,
        uint256 singleLimit,
        uint256 dailyLimit,
        uint256 duration
    ) external {
        require(agent != address(0), "Invalid agent address");
        require(singleLimit > 0 && dailyLimit > 0, "Invalid limits");
        require(singleLimit <= dailyLimit, "Single limit exceeds daily limit");

        grants[msg.sender][agent] = Grant({
            user: msg.sender,
            agent: agent,
            singleLimit: singleLimit,
            dailyLimit: dailyLimit,
            usedToday: 0,
            lastResetDate: block.timestamp / 1 days,
            expiresAt: block.timestamp + duration,
            isActive: true
        });

        emit GrantCreated(
            msg.sender,
            agent,
            singleLimit,
            dailyLimit,
            block.timestamp + duration
        );
    }

    /**
     * @dev 撤销授权
     * @param agent Agent地址
     */
    function revokeGrant(address agent) external {
        require(
            grants[msg.sender][agent].isActive,
            "Grant not found or inactive"
        );

        grants[msg.sender][agent].isActive = false;
        emit GrantRevoked(msg.sender, agent);
    }

    /**
     * @dev 执行自动支付（由Agent调用）
     * @param paymentId 支付ID
     * @param user 用户地址
     * @param recipient 收款地址
     * @param amount 支付金额
     */
    function executeAutoPayment(
        bytes32 paymentId,
        address user,
        address recipient,
        uint256 amount
    ) external nonReentrant whenNotPaused {
        require(address(paymentToken) != address(0), "Payment token not set");

        Grant storage grant = grants[user][msg.sender];
        require(grant.isActive, "Grant not active");
        require(block.timestamp <= grant.expiresAt, "Grant expired");
        require(amount <= grant.singleLimit, "Amount exceeds single limit");

        // 检查是否需要重置每日限额
        uint256 currentDate = block.timestamp / 1 days;
        if (currentDate > grant.lastResetDate) {
            grant.usedToday = 0;
            grant.lastResetDate = currentDate;
        }

        require(
            grant.usedToday + amount <= grant.dailyLimit,
            "Amount exceeds daily limit"
        );

        // 更新使用量
        grant.usedToday += amount;

        // 记录支付
        autoPayments[paymentId] = AutoPayment({
            paymentId: paymentId,
            user: user,
            agent: msg.sender,
            recipient: recipient,
            amount: amount,
            timestamp: block.timestamp,
            executed: true
        });

        // 执行转账 - 使用 SafeERC20 从用户钱包转账到收款人
        // 用户需要预先 approve 本合约
        paymentToken.safeTransferFrom(user, recipient, amount);

        emit AutoPaymentExecuted(paymentId, user, msg.sender, recipient, amount);
    }

    /**
     * @dev 查询授权信息
     * @param user 用户地址
     * @param agent Agent地址
     */
    function getGrant(address user, address agent)
        external
        view
        returns (Grant memory)
    {
        return grants[user][agent];
    }

    /**
     * @dev 查询支付记录
     * @param paymentId 支付ID
     */
    function getAutoPayment(bytes32 paymentId)
        external
        view
        returns (AutoPayment memory)
    {
        return autoPayments[paymentId];
    }

    // ============ 管理函数 ============

    /**
     * @dev 设置支付代币
     * @param _token 代币地址
     */
    function setPaymentToken(address _token) external onlyOwner {
        require(_token != address(0), "Invalid token address");
        paymentToken = IERC20(_token);
    }

    /**
     * @dev 暂停合约
     */
    function pause() external onlyOwner {
        _pause();
    }

    /**
     * @dev 恢复合约
     */
    function unpause() external onlyOwner {
        _unpause();
    }

    /**
     * @dev 紧急提款
     */
    function emergencyWithdraw(address token, address to, uint256 amount) external onlyOwner {
        require(to != address(0), "Invalid recipient");
        IERC20(token).safeTransfer(to, amount);
    }
}

contracts/BudgetPool.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/**
 * @title BudgetPool
 * @dev 预算池合约 - 用于多 Agent 协作任务的预算分配与里程碑管理
 * @notice 支持资金托管、里程碑审批、质量门控、自动释放
 * 
 * 使用场景:
 * - 多 Agent 协作完成复杂任务
 * - 按里程碑分阶段释放资金
 * - 质量审核后自动分润
 */
contract BudgetPool is Ownable, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    // ============ Constants ============
    uint16 public constant BASIS_POINTS = 10000;
    uint256 public constant MIN_POOL_AMOUNT = 1e6; // 最低 1 USDC
    uint256 public constant MAX_MILESTONES = 20;

    // ============ Enums ============
    enum PoolStatus {
        DRAFT,      // 草稿
        FUNDED,     // 已充值
        ACTIVE,     // 进行中
        COMPLETED,  // 已完成
        CANCELLED   // 已取消
    }

    enum MilestoneStatus {
        PENDING,    // 待开始
        IN_PROGRESS,// 进行中
        SUBMITTED,  // 已提交待审核
        APPROVED,   // 已批准
        REJECTED,   // 被拒绝
        RELEASED    // 已释放资金
    }

    // ============ Structs ============
    struct Pool {
        bytes32 poolId;
        address owner;
        string name;
        string description;
        uint256 totalBudget;
        uint256 fundedAmount;
        uint256 reservedAmount;
        uint256 releasedAmount;
        address token;
        PoolStatus status;
        uint256 createdAt;
        uint256 deadline;
    }

    struct Milestone {
        bytes32 milestoneId;
        bytes32 poolId;
        string title;
        string description;
        uint256 budgetAmount;
        uint16 percentOfPool;
        MilestoneStatus status;
        address[] participants;
        uint16[] participantShares; // basis points
        bytes32 deliverableHash; // 交付物哈希
        uint256 submittedAt;
        uint256 approvedAt;
        address approver;
        uint8 qualityScore; // 0-100
    }

    struct QualityGate {
        uint8 minQualityScore;   // 最低质量分 (0-100)
        bool requiresApproval;    // 是否需要人工审批
        uint256 autoReleaseDelay; // 自动释放延迟 (秒)
    }

    struct Participant {
        address wallet;
        uint256 totalEarned;
        uint256 pendingAmount;
        uint256 claimedAmount;
    }

    // ============ State Variables ============
    IERC20 public settlementToken;
    address public platformTreasury;
    uint16 public platformFeeBps; // 平台费率

    // Pools
    mapping(bytes32 => Pool) public pools;
    mapping(address => bytes32[]) public ownerPools;
    bytes32[] public allPoolIds;

    // Milestones
    mapping(bytes32 => Milestone) public milestones;
    mapping(bytes32 => bytes32[]) public poolMilestones;

    // Quality Gates
    mapping(bytes32 => QualityGate) public poolQualityGates;

    // Participants
    mapping(bytes32 => mapping(address => Participant)) public poolParticipants;
    mapping(address => uint256) public pendingBalances;

    // Access Control
    mapping(bytes32 => mapping(address => bool)) public poolApprovers;
    mapping(address => bool) public operators;

    // ============ Events ============
    event PoolCreated(
        bytes32 indexed poolId,
        address indexed owner,
        string name,
        uint256 totalBudget,
        address token
    );

    event PoolFunded(
        bytes32 indexed poolId,
        address indexed funder,
        uint256 amount
    );

    event PoolStatusChanged(
        bytes32 indexed poolId,
        PoolStatus oldStatus,
        PoolStatus newStatus
    );

    event MilestoneCreated(
        bytes32 indexed milestoneId,
        bytes32 indexed poolId,
        string title,
        uint256 budgetAmount
    );

    event MilestoneStatusChanged(
        bytes32 indexed milestoneId,
        MilestoneStatus oldStatus,
        MilestoneStatus newStatus
    );

    event MilestoneSubmitted(
        bytes32 indexed milestoneId,
        bytes32 deliverableHash,
        address indexed submitter
    );

    event MilestoneApproved(
        bytes32 indexed milestoneId,
        address indexed approver,
        uint8 qualityScore
    );

    event MilestoneRejected(
        bytes32 indexed milestoneId,
        address indexed approver,
        string reason
    );

    event FundsReleased(
        bytes32 indexed milestoneId,
        uint256 totalAmount,
        uint256 participantCount
    );

    event ParticipantPaid(
        bytes32 indexed milestoneId,
        address indexed participant,
        uint256 amount
    );

    event OperatorUpdated(address indexed operator, bool authorized);

    // ============ Modifiers ============
    modifier onlyPoolOwner(bytes32 _poolId) {
        require(pools[_poolId].owner == msg.sender, "Not pool owner");
        _;
    }

    modifier onlyPoolApprover(bytes32 _poolId) {
        require(
            pools[_poolId].owner == msg.sender ||
            poolApprovers[_poolId][msg.sender] ||
            msg.sender == owner(),
            "Not authorized approver"
        );
        _;
    }

    modifier onlyOperator() {
        require(operators[msg.sender] || msg.sender == owner(), "Not operator");
        _;
    }

    // ============ Constructor ============
    constructor(
        address _settlementToken,
        address _platformTreasury,
        uint16 _platformFeeBps
    ) {
        require(_settlementToken != address(0), "Invalid token");
        require(_platformTreasury != address(0), "Invalid treasury");
        require(_platformFeeBps <= 500, "Fee too high"); // Max 5%

        settlementToken = IERC20(_settlementToken);
        platformTreasury = _platformTreasury;
        platformFeeBps = _platformFeeBps;
    }

    // ============ Admin Functions ============

    function setPlatformFee(uint16 _feeBps) external onlyOwner {
        require(_feeBps <= 500, "Fee too high");
        platformFeeBps = _feeBps;
    }

    function setPlatformTreasury(address _treasury) external onlyOwner {
        require(_treasury != address(0), "Invalid treasury");
        platformTreasury = _treasury;
    }

    function setOperator(address _operator, bool _authorized) external onlyOwner {
        operators[_operator] = _authorized;
        emit OperatorUpdated(_operator, _authorized);
    }

    // ============ Pool Management ============

    /**
     * @dev 创建预算池
     */
    function createPool(
        string calldata _name,
        string calldata _description,
        uint256 _totalBudget,
        uint256 _deadline,
        QualityGate calldata _qualityGate
    ) external returns (bytes32 poolId) {
        require(_totalBudget >= MIN_POOL_AMOUNT, "Budget too low");
        require(_deadline > block.timestamp, "Invalid deadline");

        poolId = keccak256(abi.encodePacked(
            msg.sender,
            _name,
            block.timestamp,
            allPoolIds.length
        ));

        Pool storage pool = pools[poolId];
        pool.poolId = poolId;
        pool.owner = msg.sender;
        pool.name = _name;
        pool.description = _description;
        pool.totalBudget = _totalBudget;
        pool.token = address(settlementToken);
        pool.status = PoolStatus.DRAFT;
        pool.createdAt = block.timestamp;
        pool.deadline = _deadline;

        poolQualityGates[poolId] = _qualityGate;
        ownerPools[msg.sender].push(poolId);
        allPoolIds.push(poolId);

        emit PoolCreated(poolId, msg.sender, _name, _totalBudget, address(settlementToken));
    }

    /**
     * @dev 充值预算池
     */
    function fundPool(bytes32 _poolId, uint256 _amount) external nonReentrant {
        Pool storage pool = pools[_poolId];
        require(pool.poolId != bytes32(0), "Pool not found");
        require(pool.status == PoolStatus.DRAFT || pool.status == PoolStatus.FUNDED, "Cannot fund");
        require(_amount > 0, "Invalid amount");

        uint256 remaining = pool.totalBudget - pool.fundedAmount;
        uint256 fundAmount = _amount > remaining ? remaining : _amount;

        settlementToken.safeTransferFrom(msg.sender, address(this), fundAmount);
        pool.fundedAmount += fundAmount;

        if (pool.fundedAmount >= pool.totalBudget) {
            _changePoolStatus(_poolId, PoolStatus.FUNDED);
        }

        emit PoolFunded(_poolId, msg.sender, fundAmount);
    }

    /**
     * @dev 激活预算池
     */
    function activatePool(bytes32 _poolId) external onlyPoolOwner(_poolId) {
        Pool storage pool = pools[_poolId];
        require(pool.status == PoolStatus.FUNDED, "Not funded");
        require(poolMilestones[_poolId].length > 0, "No milestones");

        _changePoolStatus(_poolId, PoolStatus.ACTIVE);
    }

    /**
     * @dev 添加审批人
     */
    function addApprover(bytes32 _poolId, address _approver) external onlyPoolOwner(_poolId) {
        poolApprovers[_poolId][_approver] = true;
    }

    /**
     * @dev 移除审批人
     */
    function removeApprover(bytes32 _poolId, address _approver) external onlyPoolOwner(_poolId) {
        poolApprovers[_poolId][_approver] = false;
    }

    // ============ Milestone Management ============

    /**
     * @dev 创建里程碑
     */
    function createMilestone(
        bytes32 _poolId,
        string calldata _title,
        string calldata _description,
        uint16 _percentOfPool,
        address[] calldata _participants,
        uint16[] calldata _shares
    ) external onlyPoolOwner(_poolId) returns (bytes32 milestoneId) {
        Pool storage pool = pools[_poolId];
        require(pool.status == PoolStatus.DRAFT || pool.status == PoolStatus.FUNDED, "Pool not configurable");
        require(poolMilestones[_poolId].length < MAX_MILESTONES, "Too many milestones");
        require(_participants.length == _shares.length, "Length mismatch");
        require(_percentOfPool <= BASIS_POINTS, "Invalid percent");

        // 验证参与者分成总和 = 100%
        uint16 totalShares;
        for (uint i = 0; i < _shares.length; i++) {
            totalShares += _shares[i];
        }
        require(totalShares == BASIS_POINTS, "Shares must equal 100%");

        milestoneId = keccak256(abi.encodePacked(
            _poolId,
            _title,
            block.timestamp,
            poolMilestones[_poolId].length
        ));

        uint256 budgetAmount = (pool.totalBudget * _percentOfPool) / BASIS_POINTS;

        Milestone storage milestone = milestones[milestoneId];
        milestone.milestoneId = milestoneId;
        milestone.poolId = _poolId;
        milestone.title = _title;
        milestone.description = _description;
        milestone.budgetAmount = budgetAmount;
        milestone.percentOfPool = _percentOfPool;
        milestone.status = MilestoneStatus.PENDING;
        milestone.participants = _participants;
        milestone.participantShares = _shares;

        poolMilestones[_poolId].push(milestoneId);
        pool.reservedAmount += budgetAmount;

        emit MilestoneCreated(milestoneId, _poolId, _title, budgetAmount);
    }

    /**
     * @dev 开始里程碑
     */
    function startMilestone(bytes32 _milestoneId) external {
        Milestone storage milestone = milestones[_milestoneId];
        Pool storage pool = pools[milestone.poolId];
        
        require(milestone.milestoneId != bytes32(0), "Milestone not found");
        require(pool.status == PoolStatus.ACTIVE, "Pool not active");
        require(milestone.status == MilestoneStatus.PENDING, "Invalid status");
        require(_isParticipant(milestone, msg.sender) || pool.owner == msg.sender, "Not authorized");

        _changeMilestoneStatus(_milestoneId, MilestoneStatus.IN_PROGRESS);
    }

    /**
     * @dev 提交里程碑交付物
     */
    function submitMilestone(bytes32 _milestoneId, bytes32 _deliverableHash) external {
        Milestone storage milestone = milestones[_milestoneId];
        
        require(milestone.status == MilestoneStatus.IN_PROGRESS, "Not in progress");
        require(_isParticipant(milestone, msg.sender), "Not participant");

        milestone.deliverableHash = _deliverableHash;
        milestone.submittedAt = block.timestamp;
        _changeMilestoneStatus(_milestoneId, MilestoneStatus.SUBMITTED);

        emit MilestoneSubmitted(_milestoneId, _deliverableHash, msg.sender);
    }

    /**
     * @dev 批准里程碑
     */
    function approveMilestone(
        bytes32 _milestoneId,
        uint8 _qualityScore
    ) external onlyPoolApprover(milestones[_milestoneId].poolId) {
        Milestone storage milestone = milestones[_milestoneId];
        QualityGate storage gate = poolQualityGates[milestone.poolId];

        require(milestone.status == MilestoneStatus.SUBMITTED, "Not submitted");
        require(_qualityScore >= gate.minQualityScore, "Quality too low");

        milestone.qualityScore = _qualityScore;
        milestone.approver = msg.sender;
        milestone.approvedAt = block.timestamp;
        _changeMilestoneStatus(_milestoneId, MilestoneStatus.APPROVED);

        emit MilestoneApproved(_milestoneId, msg.sender, _qualityScore);
    }

    /**
     * @dev 拒绝里程碑
     */
    function rejectMilestone(
        bytes32 _milestoneId,
        string calldata _reason
    ) external onlyPoolApprover(milestones[_milestoneId].poolId) {
        Milestone storage milestone = milestones[_milestoneId];
        require(milestone.status == MilestoneStatus.SUBMITTED, "Not submitted");

        milestone.approver = msg.sender;
        _changeMilestoneStatus(_milestoneId, MilestoneStatus.REJECTED);

        emit MilestoneRejected(_milestoneId, msg.sender, _reason);
    }

    /**
     * @dev 释放里程碑资金
     */
    function releaseMilestoneFunds(bytes32 _milestoneId) external nonReentrant {
        Milestone storage milestone = milestones[_milestoneId];
        Pool storage pool = pools[milestone.poolId];
        QualityGate storage gate = poolQualityGates[milestone.poolId];

        require(milestone.status == MilestoneStatus.APPROVED, "Not approved");
        
        // 检查自动释放延迟
        if (gate.autoReleaseDelay > 0) {
            require(
                block.timestamp >= milestone.approvedAt + gate.autoReleaseDelay,
                "Release delay not met"
            );
        }

        uint256 totalAmount = milestone.budgetAmount;
        
        // 扣除平台费用
        uint256 platformFee = (totalAmount * platformFeeBps) / BASIS_POINTS;
        uint256 distributableAmount = totalAmount - platformFee;

        // 向平台转账
        if (platformFee > 0) {
            settlementToken.safeTransfer(platformTreasury, platformFee);
        }

        // 分配给参与者
        for (uint i = 0; i < milestone.participants.length; i++) {
            address participant = milestone.participants[i];
            uint256 share = (distributableAmount * milestone.participantShares[i]) / BASIS_POINTS;
            
            pendingBalances[participant] += share;
            poolParticipants[milestone.poolId][participant].pendingAmount += share;
            poolParticipants[milestone.poolId][participant].totalEarned += share;

            emit ParticipantPaid(_milestoneId, participant, share);
        }

        pool.releasedAmount += totalAmount;
        pool.reservedAmount -= totalAmount;
        _changeMilestoneStatus(_milestoneId, MilestoneStatus.RELEASED);

        // 检查是否所有里程碑都完成
        _checkPoolCompletion(milestone.poolId);

        emit FundsReleased(_milestoneId, totalAmount, milestone.participants.length);
    }

    // ============ Claim Functions ============

    /**
     * @dev 领取待领取余额
     */
    function claim() external nonReentrant {
        uint256 amount = pendingBalances[msg.sender];
        require(amount > 0, "Nothing to claim");

        pendingBalances[msg.sender] = 0;
        settlementToken.safeTransfer(msg.sender, amount);
    }

    // ============ View Functions ============

    function getPool(bytes32 _poolId) external view returns (Pool memory) {
        return pools[_poolId];
    }

    function getMilestone(bytes32 _milestoneId) external view returns (Milestone memory) {
        return milestones[_milestoneId];
    }

    function getPoolMilestones(bytes32 _poolId) external view returns (bytes32[] memory) {
        return poolMilestones[_poolId];
    }

    function getOwnerPools(address _owner) external view returns (bytes32[] memory) {
        return ownerPools[_owner];
    }

    function getQualityGate(bytes32 _poolId) external view returns (QualityGate memory) {
        return poolQualityGates[_poolId];
    }

    function getPendingBalance(address _account) external view returns (uint256) {
        return pendingBalances[_account];
    }

    function getParticipant(bytes32 _poolId, address _participant) external view returns (Participant memory) {
        return poolParticipants[_poolId][_participant];
    }

    // ============ Internal Functions ============

    function _changePoolStatus(bytes32 _poolId, PoolStatus _newStatus) internal {
        Pool storage pool = pools[_poolId];
        PoolStatus oldStatus = pool.status;
        pool.status = _newStatus;
        emit PoolStatusChanged(_poolId, oldStatus, _newStatus);
    }

    function _changeMilestoneStatus(bytes32 _milestoneId, MilestoneStatus _newStatus) internal {
        Milestone storage milestone = milestones[_milestoneId];
        MilestoneStatus oldStatus = milestone.status;
        milestone.status = _newStatus;
        emit MilestoneStatusChanged(_milestoneId, oldStatus, _newStatus);
    }

    function _isParticipant(Milestone storage _milestone, address _addr) internal view returns (bool) {
        for (uint i = 0; i < _milestone.participants.length; i++) {
            if (_milestone.participants[i] == _addr) {
                return true;
            }
        }
        return false;
    }

    function _checkPoolCompletion(bytes32 _poolId) internal {
        bytes32[] storage msIds = poolMilestones[_poolId];
        bool allReleased = true;
        
        for (uint i = 0; i < msIds.length; i++) {
            if (milestones[msIds[i]].status != MilestoneStatus.RELEASED) {
                allReleased = false;
                break;
            }
        }

        if (allReleased) {
            _changePoolStatus(_poolId, PoolStatus.COMPLETED);
        }
    }

    // ============ Pausable ============

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }
}

contracts/Commission.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/**
 * @title Commission
 * @dev 分润结算合约，管理Agent和商户的分润记录与自动结算
 * @notice 支持多场景支付分账：QuickPay (X402)、钱包直接转账、Provider 法币转数字货币
 */
contract Commission is Ownable, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;
    IERC20 public settlementToken;
    address public paymindTreasury;
    address public systemRebatePool;

    // 分润记录
    struct CommissionRecord {
        bytes32 recordId;
        address payee; // 收款方
        PayeeType payeeType;
        AgentType agentType; // Agent类型（仅当payeeType为AGENT时有效）
        uint256 amount;
        address currency; // 代币地址，address(0)表示ETH
        uint256 commissionBase; // 佣金计算基础（商户税前价格）
        uint256 channelFee; // 通道费用
        bytes32 sessionId; // Session ID（三层ID之一）
        uint256 timestamp;
        bool settled;
    }

    // 结算记录
    struct Settlement {
        bytes32 settlementId;
        address payee;
        PayeeType payeeType;
        uint256 totalAmount;
        address currency;
        uint256 settlementDate;
        bool completed;
    }

    enum PayeeType {
        AGENT,
        MERCHANT,
        PAYMIND
    }

    enum AgentType {
        EXECUTION,
        RECOMMENDATION,
        REFERRAL
    }

    enum Status {
        PENDING,
        PAID,
        PROCESSING,
        DELIVERED,
        SETTLED,
        FROZEN,
        REFUNDED
    }

    // 支付场景枚举
    enum PaymentScenario {
        QUICKPAY,      // QuickPay (X402)
        WALLET,        // 钱包直接转账
        PROVIDER_FIAT, // Provider 法币转数字货币
        PROVIDER_CRYPTO // Provider 数字货币转法币（提现）
    }

    struct Order {
        bytes32 orderId;
        address merchant;
        address referrer;
        address executor;
        uint256 merchantAmount;
        uint256 referralFee;
        uint256 executionFee;
        uint256 platformFee;
        uint256 settlementTime;
        bool executorHasWallet;
        bool isDisputed;
        Status status;
    }

    // 分账配置（链上存储）- 支持 Audit Proof
    struct SplitConfig {
        address merchantMPCWallet;  // 商户 MPC 钱包地址
        uint256 merchantAmount;     // 商户金额
        address referrer;            // 推荐人地址
        uint256 referralFee;         // 推荐人佣金
        address executor;            // 执行Agent地址
        uint256 executionFee;        // 执行Agent佣金
        uint256 platformFee;         // 平台费用
        uint256 offRampFee;          // PayMind Off-ramp分佣（可配置，默认0.1%，可为0）
        bool executorHasWallet;      // 执行Agent是否有钱包
        uint256 settlementTime;      // 结算时间（0表示即时结算）
        bool isDisputed;             // 是否有争议
        bytes32 sessionId;           // Session ID（三层ID之一）
        // Audit Proof 扩展字段
        bytes32 proofHash;           // 预期结果哈希（用于验证任务完成）
        address auditor;             // 审计员地址（验证任务完成的签名者）
        bool requiresProof;          // 是否需要 Proof 才能释放资金
        bool proofVerified;          // Proof 是否已验证
    }

    // 事件
    event CommissionRecorded(
        bytes32 indexed recordId,
        address indexed payee,
        PayeeType payeeType,
        AgentType agentType,
        uint256 amount,
        address currency,
        uint256 commissionBase,
        uint256 channelFee,
        bytes32 sessionId
    );

    event SettlementCreated(
        bytes32 indexed settlementId,
        address indexed payee,
        PayeeType payeeType,
        uint256 totalAmount,
        address currency
    );

    event SettlementCompleted(
        bytes32 indexed settlementId,
        address indexed payee,
        uint256 amount,
        address currency
    );

    event OrderSynced(bytes32 indexed orderId, Status status, uint256 settlementTime);
    event CommissionDistributed(bytes32 indexed orderId, uint256 merchantAmount);

    // 新的事件
    event PaymentReceived(
        bytes32 indexed orderId,
        PaymentScenario scenario,
        address indexed from,
        uint256 amount
    );

    event PaymentAutoSplit(
        bytes32 indexed orderId,
        bytes32 indexed sessionId,
        address indexed merchantWallet,
        uint256 totalAmount,
        uint256 merchantAmount,
        uint256 platformFee,
        uint256 executionFee,
        uint256 referralFee
    );

    event SplitConfigSet(bytes32 indexed orderId, SplitConfig config);
    event ProviderAuthorized(address indexed provider, bool authorized);

    // Audit Proof 事件
    event ProofSubmitted(bytes32 indexed orderId, bytes32 resultHash, address indexed submitter);
    event ProofVerified(bytes32 indexed orderId, bytes32 resultHash, address indexed auditor, uint256 quality);
    event ProofRejected(bytes32 indexed orderId, string reason, address indexed auditor);
    event TrustedAuditorUpdated(address indexed auditor, bool trusted);

    // 状态变量
    mapping(bytes32 => CommissionRecord) public commissions;
    mapping(bytes32 => Settlement) public settlements;
    mapping(address => mapping(address => uint256)) public pendingBalances; // payee => currency => amount
    mapping(bytes32 => Order) public orders;

    // 新状态变量
    mapping(bytes32 => SplitConfig) public orderSplitConfigs; // 订单分账配置
    mapping(address => bool) public authorizedProviders; // Provider 白名单
    mapping(address => bool) public relayers; // Relayer 白名单

    // Audit Proof 状态变量
    mapping(address => bool) public trustedAuditors; // 受信任的审计员
    mapping(bytes32 => bytes32) public submittedProofs; // orderId => submittedResultHash

    modifier onlyRelayer() {
        require(relayers[msg.sender] || msg.sender == owner(), "Not relayer");
        _;
    }

    modifier onlyAuditor(bytes32 orderId) {
        SplitConfig storage config = orderSplitConfigs[orderId];
        require(
            trustedAuditors[msg.sender] || 
            config.auditor == msg.sender || 
            msg.sender == owner(),
            "Not authorized auditor"
        );
        _;
    }

    function setRelayer(address relayer, bool active) external onlyOwner {
        relayers[relayer] = active;
    }

    function configureSettlementToken(
        address token,
        address treasury,
        address rebatePool
    ) external onlyOwner {
        require(token != address(0) && treasury != address(0), "Invalid addresses");
        settlementToken = IERC20(token);
        paymindTreasury = treasury;
        systemRebatePool = rebatePool;
    }

    function updateSystemRebatePool(address rebatePool) external onlyOwner {
        systemRebatePool = rebatePool;
    }

    function syncOrder(
        bytes32 orderId,
        address merchant,
        address referrer,
        address executor,
        uint256 merchantAmount,
        uint256 referralFee,
        uint256 executionFee,
        uint256 platformFee,
        uint256 settlementTime,
        bool executorHasWallet,
        bool isDisputed,
        Status status
    ) external onlyOwner {
        require(orderId != bytes32(0), "Invalid order");
        Order storage o = orders[orderId];
        o.orderId = orderId;
        o.merchant = merchant;
        o.referrer = referrer;
        o.executor = executor;
        o.merchantAmount = merchantAmount;
        o.referralFee = referralFee;
        o.executionFee = executionFee;
        o.platformFee = platformFee;
        o.settlementTime = settlementTime;
        o.executorHasWallet = executorHasWallet;
        o.isDisputed = isDisputed;
        o.status = status;

        emit OrderSynced(orderId, status, settlementTime);
    }

    function setOrderDispute(bytes32 orderId, bool disputed) external onlyOwner {
        Order storage o = orders[orderId];
        require(o.orderId != bytes32(0), "Order not found");
        o.isDisputed = disputed;
        o.status = disputed ? Status.FROZEN : o.status;
    }

    /**
     * @dev 兼容现有的 distributeCommission 函数
     * 支持两种模式：
     * 1. 使用新的 SplitConfig（如果已设置）
     * 2. 使用旧的 Order 结构（向后兼容）
     * 
     * 如果 SplitConfig.requiresProof = true，则必须先验证 proof
     */
    function distributeCommission(bytes32 orderId) external nonReentrant {
        // 优先使用新的 SplitConfig
        SplitConfig storage config = orderSplitConfigs[orderId];
        if (config.merchantMPCWallet != address(0)) {
            // 检查是否需要 Proof 验证
            if (config.requiresProof) {
                require(config.proofVerified, "Proof not verified");
            }

            // 使用新的分账配置
            uint256 contractBalance = settlementToken.balanceOf(address(this));
            require(contractBalance > 0, "No balance to distribute");

            uint256 totalAmount = config.merchantAmount + 
                                 config.referralFee + 
                                 config.executionFee + 
                                 config.platformFee;

            if (totalAmount == 0) {
                totalAmount = contractBalance;
            }

            _autoSplit(orderId, totalAmount);
            return;
        }

        // 向后兼容：使用旧的 Order 结构
        Order storage o = orders[orderId];
        require(o.orderId != bytes32(0), "Order not found");
        require(o.status == Status.DELIVERED, "Order not ready");
        require(!o.isDisputed, "Order is disputed");
        require(block.timestamp >= o.settlementTime, "Still in locking period");
        require(address(settlementToken) != address(0), "Token not configured");
        require(paymindTreasury != address(0), "Treasury not configured");

        if (o.merchant != address(0) && o.merchantAmount > 0) {
            settlementToken.safeTransfer(o.merchant, o.merchantAmount);
        }

        if (o.referralFee > 0 && o.referrer != address(0)) {
            settlementToken.safeTransfer(o.referrer, o.referralFee);
        }

        if (o.executionFee > 0) {
            address target = o.executorHasWallet ? o.executor : systemRebatePool;
            if (target == address(0)) {
                target = paymindTreasury;
            }
            settlementToken.safeTransfer(target, o.executionFee);
        }

        if (o.platformFee > 0) {
            settlementToken.safeTransfer(paymindTreasury, o.platformFee);
        }

        o.status = Status.SETTLED;
        emit CommissionDistributed(orderId, o.merchantAmount);
    }

    /**
     * @dev 记录分润（新版本，支持多Agent协作和Session ID）
     * @param payee 收款方地址
     * @param payeeType 收款方类型
     * @param agentType Agent类型（仅当payeeType为AGENT时有效）
     * @param amount 分润金额
     * @param currency 代币地址
     * @param commissionBase 佣金计算基础（商户税前价格）
     * @param channelFee 通道费用
     * @param sessionId Session ID（三层ID之一）
     */
    function recordCommission(
        address payee,
        PayeeType payeeType,
        AgentType agentType,
        uint256 amount,
        address currency,
        uint256 commissionBase,
        uint256 channelFee,
        bytes32 sessionId
    ) external onlyOwner {
        require(payee != address(0), "Invalid payee address");
        require(amount > 0, "Amount must be greater than 0");

        bytes32 recordId = keccak256(
            abi.encodePacked(
                payee,
                payeeType,
                agentType,
                amount,
                currency,
                commissionBase,
                channelFee,
                sessionId,
                block.timestamp
            )
        );

        commissions[recordId] = CommissionRecord({
            recordId: recordId,
            payee: payee,
            payeeType: payeeType,
            agentType: agentType,
            amount: amount,
            currency: currency,
            commissionBase: commissionBase,
            channelFee: channelFee,
            sessionId: sessionId,
            timestamp: block.timestamp,
            settled: false
        });

        pendingBalances[payee][currency] += amount;

        emit CommissionRecorded(
            recordId,
            payee,
            payeeType,
            agentType,
            amount,
            currency,
            commissionBase,
            channelFee,
            sessionId
        );
    }

    /**
     * @dev 记录分润（旧版本，保持向后兼容）
     * @param payee 收款方地址
     * @param payeeType 收款方类型
     * @param amount 分润金额
     * @param currency 代币地址
     */
    function recordCommissionLegacy(
        address payee,
        PayeeType payeeType,
        uint256 amount,
        address currency
    ) external onlyOwner {
        require(payee != address(0), "Invalid payee address");
        require(amount > 0, "Amount must be greater than 0");

        bytes32 recordId = keccak256(
            abi.encodePacked(
                payee,
                payeeType,
                amount,
                currency,
                block.timestamp
            )
        );

        commissions[recordId] = CommissionRecord({
            recordId: recordId,
            payee: payee,
            payeeType: payeeType,
            agentType: AgentType.EXECUTION, // 默认执行Agent
            amount: amount,
            currency: currency,
            commissionBase: amount, // 默认使用amount作为基础
            channelFee: 0,
            sessionId: bytes32(0),
            timestamp: block.timestamp,
            settled: false
        });

        pendingBalances[payee][currency] += amount;

        emit CommissionRecorded(
            recordId,
            payee,
            payeeType,
            AgentType.EXECUTION,
            amount,
            currency,
            amount,
            0,
            bytes32(0)
        );
    }

    /**
     * @dev 创建结算
     * @param payee 收款方地址
     * @param payeeType 收款方类型
     * @param currency 代币地址
     */
    function createSettlement(
        address payee,
        PayeeType payeeType,
        address currency
    ) external onlyOwner returns (bytes32) {
        uint256 totalAmount = pendingBalances[payee][currency];
        require(totalAmount > 0, "No pending balance");

        bytes32 settlementId = keccak256(
            abi.encodePacked(
                payee,
                payeeType,
                currency,
                block.timestamp
            )
        );

        settlements[settlementId] = Settlement({
            settlementId: settlementId,
            payee: payee,
            payeeType: payeeType,
            totalAmount: totalAmount,
            currency: currency,
            settlementDate: block.timestamp,
            completed: false
        });

        emit SettlementCreated(
            settlementId,
            payee,
            payeeType,
            totalAmount,
            currency
        );

        return settlementId;
    }

    /**
     * @dev 执行结算
     * @param settlementId 结算ID
     */
    function executeSettlement(bytes32 settlementId) external nonReentrant {
        Settlement storage settlement = settlements[settlementId];
        require(settlement.settlementId != bytes32(0), "Settlement not found");
        require(!settlement.completed, "Settlement already completed");

        uint256 amount = settlement.totalAmount;
        address currency = settlement.currency;

        // 清零待结算余额
        pendingBalances[settlement.payee][currency] = 0;

        // 执行转账
        if (currency == address(0)) {
            // ETH转账 - 使用 call 替代 transfer 以支持更高 gas 限制
            (bool success, ) = payable(settlement.payee).call{value: amount}("");
            require(success, "ETH transfer failed");
        } else {
            // ERC20代币转账 - 使用 SafeERC20
            IERC20 token = IERC20(currency);
            require(
                token.balanceOf(address(this)) >= amount,
                "Insufficient token balance"
            );
            token.safeTransfer(settlement.payee, amount);
        }

        settlement.completed = true;

        emit SettlementCompleted(
            settlementId,
            settlement.payee,
            amount,
            currency
        );
    }

    /**
     * @dev 查询待结算余额
     * @param payee 收款方地址
     * @param currency 代币地址
     */
    function getPendingBalance(address payee, address currency)
        external
        view
        returns (uint256)
    {
        return pendingBalances[payee][currency];
    }

    // ============ 统一分账函数 ============

    /**
     * @dev 统一的分账函数（内部函数）
     * @param orderId 订单ID
     * @param totalAmount 总金额
     */
    function _autoSplit(bytes32 orderId, uint256 totalAmount) internal {
        SplitConfig storage config = orderSplitConfigs[orderId];
        require(config.merchantMPCWallet != address(0), "Order config not found");
        require(!config.isDisputed, "Order is disputed");

        // 验证结算时间（如果需要）
        if (config.settlementTime > 0) {
            require(
                block.timestamp >= config.settlementTime,
                "Settlement time not reached"
            );
        }

        // 验证 USDC 余额
        require(
            settlementToken.balanceOf(address(this)) >= totalAmount,
            "Insufficient USDC balance"
        );

        // 记录已分配金额，用于防止精度损失
        uint256 distributed = 0;

        // 分账到商户 MPC 钱包
        if (config.merchantMPCWallet != address(0) && config.merchantAmount > 0) {
            settlementToken.safeTransfer(config.merchantMPCWallet, config.merchantAmount);
            distributed += config.merchantAmount;
        }

        // 分账到推荐人
        if (config.referralFee > 0 && config.referrer != address(0)) {
            settlementToken.safeTransfer(config.referrer, config.referralFee);
            distributed += config.referralFee;
        }

        // 分账到执行Agent
        if (config.executionFee > 0) {
            address target = config.executorHasWallet 
                ? config.executor 
                : systemRebatePool;
            if (target == address(0)) {
                target = paymindTreasury;
            }
            settlementToken.safeTransfer(target, config.executionFee);
            distributed += config.executionFee;
        }

        // 分账到平台
        if (config.platformFee > 0) {
            settlementToken.safeTransfer(paymindTreasury, config.platformFee);
            distributed += config.platformFee;
        }

        // 分账到PayMind Treasury（Off-ramp分佣，可配置，可为0）
        if (config.offRampFee > 0) {
            settlementToken.safeTransfer(paymindTreasury, config.offRampFee);
            distributed += config.offRampFee;
        }

        // 处理精度损失：将剩余金额转给平台
        if (totalAmount > distributed) {
            uint256 remaining = totalAmount - distributed;
            settlementToken.safeTransfer(paymindTreasury, remaining);
        }

        // 记录分账事件
        emit PaymentAutoSplit(
            orderId,
            config.sessionId,
            config.merchantMPCWallet,
            totalAmount,
            config.merchantAmount,
            config.platformFee,
            config.executionFee,
            config.referralFee
        );
    }

    // ============ 场景 1: QuickPay (X402) ============

    /**
     * @dev QuickPay 支付（X402 Session）
     * 注意：Session 签名验证应该在调用此函数之前完成（由 ERC8004 合约或 Relayer 验证）
     * @param orderId 订单ID
     * @param amount 支付金额
     */
    function quickPaySplit(
        bytes32 orderId,
        uint256 amount
    ) external nonReentrant whenNotPaused {
        // 1. 从用户钱包转账 USDC 到合约 - 使用 SafeERC20
        settlementToken.safeTransferFrom(msg.sender, address(this), amount);

        // 2. 记录支付
        emit PaymentReceived(orderId, PaymentScenario.QUICKPAY, msg.sender, amount);

        // 3. 自动分账
        _autoSplit(orderId, amount);
    }

    /**
     * @dev QuickPay 支付（通过 Relayer/SessionManager）
     * 允许 Relayer 指定付款人（前提是 Relayer 已验证 Session）
     * @param orderId 订单ID
     * @param amount 支付金额
     * @param payer 付款人地址
     */
    function quickPaySplitFrom(
        bytes32 orderId,
        uint256 amount,
        address payer
    ) external nonReentrant onlyRelayer whenNotPaused {
        // 1. 从指定付款人钱包转账 USDC 到合约 - 使用 SafeERC20
        // 注意：付款人必须已授权 Commission 合约（或通过 Permit）
        settlementToken.safeTransferFrom(payer, address(this), amount);

        // 2. 记录支付
        emit PaymentReceived(orderId, PaymentScenario.QUICKPAY, payer, amount);

        // 3. 自动分账
        _autoSplit(orderId, amount);
    }

    // ============ 场景 2: 钱包直接转账 ============

    /**
     * @dev 钱包直接转账分账
     * @param orderId 订单ID
     * @param amount 支付金额
     */
    function walletSplit(
        bytes32 orderId,
        uint256 amount
    ) external nonReentrant whenNotPaused {
        // 1. 从用户钱包转账 USDC 到合约 - 使用 SafeERC20
        settlementToken.safeTransferFrom(msg.sender, address(this), amount);

        // 2. 记录支付
        emit PaymentReceived(orderId, PaymentScenario.WALLET, msg.sender, amount);

        // 3. 自动分账
        _autoSplit(orderId, amount);
    }

    // ============ 场景 3: Provider 法币转数字货币 ============

    /**
     * @dev Provider 发送 USDC 到合约并自动分账
     * @param orderId 订单ID
     * @param amount 支付金额
     */
    function providerFiatToCryptoSplit(
        bytes32 orderId,
        uint256 amount
    ) external nonReentrant whenNotPaused {
        // 1. 验证 Provider 地址（白名单）
        require(authorizedProviders[msg.sender], "Unauthorized provider");

        // 2. 从 Provider 钱包转账 USDC 到合约 - 使用 SafeERC20
        // 验证转账前后余额变化，防止转账金额不匹配
        uint256 balanceBefore = settlementToken.balanceOf(address(this));
        settlementToken.safeTransferFrom(msg.sender, address(this), amount);
        uint256 balanceAfter = settlementToken.balanceOf(address(this));
        require(balanceAfter - balanceBefore >= amount, "Transfer amount mismatch");

        // 3. 记录支付
        emit PaymentReceived(orderId, PaymentScenario.PROVIDER_FIAT, msg.sender, amount);

        // 4. 自动分账
        _autoSplit(orderId, amount);
    }

    // ============ 配置函数 ============

    /**
     * @dev 设置订单分账配置
     * @param orderId 订单ID
     * @param config 分账配置
     */
    function setSplitConfig(
        bytes32 orderId,
        SplitConfig memory config
    ) external {
        require(msg.sender == owner() || relayers[msg.sender], "Unauthorized");
        require(config.merchantMPCWallet != address(0), "Invalid merchant wallet");
        orderSplitConfigs[orderId] = config;
        emit SplitConfigSet(orderId, config);
    }

    /**
     * @dev 设置 Provider 白名单（可选）
     */
    function setAuthorizedProvider(address provider, bool authorized) external onlyOwner {
        authorizedProviders[provider] = authorized;
        emit ProviderAuthorized(provider, authorized);
    }

    /**
     * @dev 设置争议状态
     */
    function setDisputeStatus(bytes32 orderId, bool isDisputed) external onlyOwner {
        SplitConfig storage config = orderSplitConfigs[orderId];
        require(config.merchantMPCWallet != address(0), "Order not found");
        config.isDisputed = isDisputed;
    }

    // ============ 查询函数 ============

    /**
     * @dev 查询订单分账配置
     */
    function getSplitConfig(bytes32 orderId) 
        external 
        view 
        returns (SplitConfig memory) 
    {
        return orderSplitConfigs[orderId];
    }

    /**
     * @dev 查询合约 USDC 余额
     */
    function getContractBalance() external view returns (uint256) {
        return settlementToken.balanceOf(address(this));
    }

    // ============ 紧急控制函数 ============

    /**
     * @dev 暂停合约
     */
    function pause() external onlyOwner {
        _pause();
    }

    /**
     * @dev 恢复合约
     */
    function unpause() external onlyOwner {
        _unpause();
    }

    /**
     * @dev 紧急提款 ERC20 代币
     * @param token 代币地址
     * @param to 接收地址
     * @param amount 金额
     */
    function emergencyWithdrawToken(
        address token,
        address to,
        uint256 amount
    ) external onlyOwner {
        require(to != address(0), "Invalid recipient");
        IERC20(token).safeTransfer(to, amount);
    }

    /**
     * @dev 紧急提款 ETH
     * @param to 接收地址
     * @param amount 金额
     */
    function emergencyWithdrawETH(
        address to,
        uint256 amount
    ) external onlyOwner {
        require(to != address(0), "Invalid recipient");
        require(address(this).balance >= amount, "Insufficient balance");
        (bool success, ) = payable(to).call{value: amount}("");
        require(success, "ETH transfer failed");
    }

    // ============ Audit Proof 函数 ============

    /**
     * @dev 设置受信任的审计员
     */
    function setTrustedAuditor(address auditor, bool trusted) external onlyOwner {
        trustedAuditors[auditor] = trusted;
        emit TrustedAuditorUpdated(auditor, trusted);
    }

    /**
     * @dev 设置订单的 Proof 要求
     * @param orderId 订单 ID
     * @param proofHash 预期结果哈希
     * @param auditor 指定审计员（可选，address(0) 表示使用全局审计员）
     */
    function setProofRequirement(
        bytes32 orderId,
        bytes32 proofHash,
        address auditor
    ) external onlyRelayer {
        SplitConfig storage config = orderSplitConfigs[orderId];
        require(config.merchantMPCWallet != address(0), "Config not found");

        config.proofHash = proofHash;
        config.auditor = auditor;
        config.requiresProof = true;
        config.proofVerified = false;
    }

    /**
     * @dev 执行者提交任务结果哈希
     * @param orderId 订单 ID
     * @param resultHash 结果哈希（如图片哈希）
     */
    function submitProof(bytes32 orderId, bytes32 resultHash) external {
        SplitConfig storage config = orderSplitConfigs[orderId];
        require(config.requiresProof, "Proof not required");
        require(!config.proofVerified, "Already verified");
        require(
            msg.sender == config.executor || msg.sender == config.merchantMPCWallet,
            "Not authorized"
        );

        submittedProofs[orderId] = resultHash;
        emit ProofSubmitted(orderId, resultHash, msg.sender);

        // 如果预期哈希匹配，自动验证
        if (config.proofHash != bytes32(0) && resultHash == config.proofHash) {
            config.proofVerified = true;
            emit ProofVerified(orderId, resultHash, address(this), 100);
        }
    }

    /**
     * @dev 审计员验证 Proof
     * @param orderId 订单 ID
     * @param approved 是否通过
     * @param quality 质量评分 (0-100)
     */
    function verifyProof(
        bytes32 orderId,
        bool approved,
        uint256 quality
    ) external onlyAuditor(orderId) {
        SplitConfig storage config = orderSplitConfigs[orderId];
        require(config.requiresProof, "Proof not required");
        require(!config.proofVerified, "Already verified");
        require(submittedProofs[orderId] != bytes32(0), "No proof submitted");

        if (approved && quality >= 60) {
            config.proofVerified = true;
            emit ProofVerified(orderId, submittedProofs[orderId], msg.sender, quality);
        } else {
            emit ProofRejected(orderId, "Quality insufficient or rejected", msg.sender);
        }
    }

    /**
     * @dev 查询订单的 Proof 状态
     */
    function getProofStatus(bytes32 orderId) external view returns (
        bool requiresProof,
        bytes32 expectedHash,
        bytes32 submittedHash,
        bool verified,
        address auditor
    ) {
        SplitConfig storage config = orderSplitConfigs[orderId];
        return (
            config.requiresProof,
            config.proofHash,
            submittedProofs[orderId],
            config.proofVerified,
            config.auditor
        );
    }

    /**
     * @dev 接收ETH
     */
    receive() external payable {}
}

contracts/CommissionV2.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/**
 * @title CommissionV2
 * @dev Commerce Skill 统一分润结算合约
 * @notice 整合 Payment + Commission，支持统一费率体系
 * 
 * 费率结构 (basis points, 10000 = 100%):
 * - 纯链上 Crypto 支付: 0% (免费)
 * - On-ramp (Transak 买币): +0.1% (10 bps)
 * - Off-ramp (Transak 提现): +0.1% (10 bps)
 * - Split 分润: 0.3% (30 bps), 最低 0.1 USDC (100000 micro)
 */
contract CommissionV2 is Ownable, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    // ============ Constants ============
    uint16 public constant BASIS_POINTS = 10000; // 100% = 10000
    uint256 public constant MICRO_UNIT = 1e6; // 1 USDC = 1000000

    // ============ Fee Configuration ============
    struct FeeConfig {
        uint16 onrampFeeBps;   // On-ramp 额外费率 (默认 10 = 0.1%)
        uint16 offrampFeeBps;  // Off-ramp 额外费率 (默认 10 = 0.1%)
        uint16 splitFeeBps;    // Split 费率 (默认 30 = 0.3%)
        uint256 minSplitFee;   // 最低 Split 费用 (默认 100000 = 0.1 USDC)
    }

    // ============ Split Plan ============
    struct SplitPlan {
        bytes32 planId;
        address owner;
        string name;
        SplitRule[] rules;
        FeeConfig feeConfig;
        bool active;
        uint256 createdAt;
        uint256 updatedAt;
    }

    struct SplitRule {
        address recipient;
        uint16 shareBps; // 分成比例 (basis points)
        string role;     // 角色标识: "platform", "merchant", "agent", "referrer"
    }

    // ============ Split Execution ============
    struct SplitExecution {
        bytes32 executionId;
        bytes32 planId;
        bytes32 sessionId;
        uint256 totalAmount;
        uint256 platformFee;
        address token;
        uint256 executedAt;
        bool completed;
    }

    struct Allocation {
        address recipient;
        uint256 amount;
        uint256 fee;
        bool claimed;
    }

    // ============ Payment Types ============
    enum PaymentType {
        CRYPTO_DIRECT, // 纯链上支付 (0%)
        ONRAMP,        // Transak 买币 (+0.1%)
        OFFRAMP,       // Transak 提现 (+0.1%)
        MIXED          // 混合场景
    }

    // ============ State Variables ============
    IERC20 public settlementToken;
    address public platformTreasury;
    FeeConfig public defaultFeeConfig;

    // Split Plans
    mapping(bytes32 => SplitPlan) public splitPlans;
    mapping(address => bytes32[]) public ownerPlans;
    bytes32[] public allPlanIds;

    // Split Executions
    mapping(bytes32 => SplitExecution) public executions;
    mapping(bytes32 => Allocation[]) public executionAllocations;
    mapping(address => uint256) public pendingBalances;

    // Access Control
    mapping(address => bool) public operators;
    mapping(address => bool) public relayers;

    // ============ Events ============
    event FeeConfigUpdated(
        uint16 onrampFeeBps,
        uint16 offrampFeeBps,
        uint16 splitFeeBps,
        uint256 minSplitFee
    );

    event SplitPlanCreated(
        bytes32 indexed planId,
        address indexed owner,
        string name,
        uint256 rulesCount
    );

    event SplitPlanUpdated(
        bytes32 indexed planId,
        address indexed owner,
        bool active
    );

    event SplitExecuted(
        bytes32 indexed executionId,
        bytes32 indexed planId,
        bytes32 indexed sessionId,
        uint256 totalAmount,
        uint256 platformFee,
        PaymentType paymentType
    );

    event AllocationClaimed(
        bytes32 indexed executionId,
        address indexed recipient,
        uint256 amount
    );

    event OperatorUpdated(address indexed operator, bool authorized);
    event RelayerUpdated(address indexed relayer, bool authorized);

    // ============ Modifiers ============
    modifier onlyOperator() {
        require(operators[msg.sender] || msg.sender == owner(), "Not operator");
        _;
    }

    modifier onlyRelayer() {
        require(relayers[msg.sender] || msg.sender == owner(), "Not relayer");
        _;
    }

    // ============ Constructor ============
    constructor(
        address _settlementToken,
        address _platformTreasury
    ) {
        require(_settlementToken != address(0), "Invalid token");
        require(_platformTreasury != address(0), "Invalid treasury");
        
        settlementToken = IERC20(_settlementToken);
        platformTreasury = _platformTreasury;
        
        // 设置默认费率
        defaultFeeConfig = FeeConfig({
            onrampFeeBps: 10,   // 0.1%
            offrampFeeBps: 10,  // 0.1%
            splitFeeBps: 30,    // 0.3%
            minSplitFee: 100000 // 0.1 USDC
        });
    }

    // ============ Admin Functions ============

    /**
     * @dev 更新默认费率配置
     */
    function updateDefaultFeeConfig(
        uint16 _onrampFeeBps,
        uint16 _offrampFeeBps,
        uint16 _splitFeeBps,
        uint256 _minSplitFee
    ) external onlyOwner {
        require(_onrampFeeBps <= 100, "Onramp fee too high"); // Max 1%
        require(_offrampFeeBps <= 100, "Offramp fee too high");
        require(_splitFeeBps <= 100, "Split fee too high");
        
        defaultFeeConfig = FeeConfig({
            onrampFeeBps: _onrampFeeBps,
            offrampFeeBps: _offrampFeeBps,
            splitFeeBps: _splitFeeBps,
            minSplitFee: _minSplitFee
        });
        
        emit FeeConfigUpdated(_onrampFeeBps, _offrampFeeBps, _splitFeeBps, _minSplitFee);
    }

    function setOperator(address _operator, bool _authorized) external onlyOwner {
        operators[_operator] = _authorized;
        emit OperatorUpdated(_operator, _authorized);
    }

    function setRelayer(address _relayer, bool _authorized) external onlyOwner {
        relayers[_relayer] = _authorized;
        emit RelayerUpdated(_relayer, _authorized);
    }

    function setPlatformTreasury(address _treasury) external onlyOwner {
        require(_treasury != address(0), "Invalid treasury");
        platformTreasury = _treasury;
    }

    // ============ Split Plan Management ============

    /**
     * @dev 创建分润方案
     */
    function createSplitPlan(
        string calldata _name,
        address[] calldata _recipients,
        uint16[] calldata _shares,
        string[] calldata _roles,
        FeeConfig calldata _feeConfig
    ) external returns (bytes32 planId) {
        require(_recipients.length == _shares.length, "Length mismatch");
        require(_recipients.length == _roles.length, "Length mismatch");
        require(_recipients.length > 0, "No recipients");
        
        // 验证分成比例总和 = 100%
        uint16 totalShares;
        for (uint i = 0; i < _shares.length; i++) {
            totalShares += _shares[i];
        }
        require(totalShares == BASIS_POINTS, "Shares must equal 100%");
        
        planId = keccak256(abi.encodePacked(msg.sender, _name, block.timestamp, allPlanIds.length));
        
        SplitPlan storage plan = splitPlans[planId];
        plan.planId = planId;
        plan.owner = msg.sender;
        plan.name = _name;
        plan.feeConfig = _feeConfig;
        plan.active = true;
        plan.createdAt = block.timestamp;
        plan.updatedAt = block.timestamp;
        
        for (uint i = 0; i < _recipients.length; i++) {
            require(_recipients[i] != address(0), "Invalid recipient");
            plan.rules.push(SplitRule({
                recipient: _recipients[i],
                shareBps: _shares[i],
                role: _roles[i]
            }));
        }
        
        ownerPlans[msg.sender].push(planId);
        allPlanIds.push(planId);
        
        emit SplitPlanCreated(planId, msg.sender, _name, _recipients.length);
    }

    /**
     * @dev 激活/停用分润方案
     */
    function setSplitPlanActive(bytes32 _planId, bool _active) external {
        SplitPlan storage plan = splitPlans[_planId];
        require(plan.owner == msg.sender || msg.sender == owner(), "Not authorized");
        require(plan.planId != bytes32(0), "Plan not found");
        
        plan.active = _active;
        plan.updatedAt = block.timestamp;
        
        emit SplitPlanUpdated(_planId, msg.sender, _active);
    }

    // ============ Split Execution ============

    /**
     * @dev 计算平台费用
     */
    function calculatePlatformFee(
        uint256 _amount,
        PaymentType _paymentType,
        FeeConfig memory _config
    ) public pure returns (uint256 fee) {
        // 纯链上支付免费
        if (_paymentType == PaymentType.CRYPTO_DIRECT) {
            return 0;
        }
        
        // 基础 Split 费用
        fee = (_amount * _config.splitFeeBps) / BASIS_POINTS;
        
        // 确保最低费用
        if (fee < _config.minSplitFee) {
            fee = _config.minSplitFee;
        }
        
        // On-ramp 额外费用
        if (_paymentType == PaymentType.ONRAMP || _paymentType == PaymentType.MIXED) {
            fee += (_amount * _config.onrampFeeBps) / BASIS_POINTS;
        }
        
        // Off-ramp 额外费用
        if (_paymentType == PaymentType.OFFRAMP || _paymentType == PaymentType.MIXED) {
            fee += (_amount * _config.offrampFeeBps) / BASIS_POINTS;
        }
    }

    /**
     * @dev 执行分润
     * @param _planId 分润方案ID
     * @param _sessionId 会话ID
     * @param _amount 总金额
     * @param _paymentType 支付类型
     */
    function executeSplit(
        bytes32 _planId,
        bytes32 _sessionId,
        uint256 _amount,
        PaymentType _paymentType
    ) external nonReentrant whenNotPaused onlyRelayer returns (bytes32 executionId) {
        SplitPlan storage plan = splitPlans[_planId];
        require(plan.active, "Plan not active");
        require(_amount > 0, "Invalid amount");
        
        // 计算平台费用
        uint256 platformFee = calculatePlatformFee(_amount, _paymentType, plan.feeConfig);
        uint256 distributableAmount = _amount - platformFee;
        
        // 生成执行ID
        executionId = keccak256(abi.encodePacked(_planId, _sessionId, block.timestamp));
        
        // 创建执行记录
        SplitExecution storage execution = executions[executionId];
        execution.executionId = executionId;
        execution.planId = _planId;
        execution.sessionId = _sessionId;
        execution.totalAmount = _amount;
        execution.platformFee = platformFee;
        execution.token = address(settlementToken);
        execution.executedAt = block.timestamp;
        execution.completed = false;
        
        // 计算每个参与者的分配（处理精度损失）
        uint256 totalAllocated = 0;
        for (uint i = 0; i < plan.rules.length; i++) {
            SplitRule memory rule = plan.rules[i];
            uint256 allocation = (distributableAmount * rule.shareBps) / BASIS_POINTS;
            totalAllocated += allocation;
            
            executionAllocations[executionId].push(Allocation({
                recipient: rule.recipient,
                amount: allocation,
                fee: 0,
                claimed: false
            }));
            
            // 累加待领取余额
            pendingBalances[rule.recipient] += allocation;
        }
        
        // 处理精度损失：将剩余 dust 分配给第一个参与者
        if (distributableAmount > totalAllocated && plan.rules.length > 0) {
            uint256 dust = distributableAmount - totalAllocated;
            executionAllocations[executionId][0].amount += dust;
            pendingBalances[plan.rules[0].recipient] += dust;
        }
        
        // 平台费用直接转入 Treasury
        if (platformFee > 0) {
            settlementToken.safeTransferFrom(msg.sender, platformTreasury, platformFee);
        }
        
        // 标记完成
        execution.completed = true;
        
        emit SplitExecuted(
            executionId,
            _planId,
            _sessionId,
            _amount,
            platformFee,
            _paymentType
        );
    }

    /**
     * @dev 领取分润
     */
    function claimAllocation(bytes32 _executionId, uint256 _index) external nonReentrant {
        Allocation storage allocation = executionAllocations[_executionId][_index];
        require(allocation.recipient == msg.sender, "Not recipient");
        require(!allocation.claimed, "Already claimed");
        require(allocation.amount > 0, "Nothing to claim");
        
        allocation.claimed = true;
        pendingBalances[msg.sender] -= allocation.amount;
        
        settlementToken.safeTransfer(msg.sender, allocation.amount);
        
        emit AllocationClaimed(_executionId, msg.sender, allocation.amount);
    }

    /**
     * @dev 批量领取所有待领取余额
     */
    function claimAll() external nonReentrant {
        uint256 balance = pendingBalances[msg.sender];
        require(balance > 0, "Nothing to claim");
        
        pendingBalances[msg.sender] = 0;
        settlementToken.safeTransfer(msg.sender, balance);
        
        emit AllocationClaimed(bytes32(0), msg.sender, balance);
    }

    // ============ View Functions ============

    function getSplitPlan(bytes32 _planId) external view returns (
        bytes32 planId,
        address owner_,
        string memory name,
        bool active,
        uint256 rulesCount,
        FeeConfig memory feeConfig,
        uint256 createdAt
    ) {
        SplitPlan storage plan = splitPlans[_planId];
        return (
            plan.planId,
            plan.owner,
            plan.name,
            plan.active,
            plan.rules.length,
            plan.feeConfig,
            plan.createdAt
        );
    }

    function getSplitRules(bytes32 _planId) external view returns (SplitRule[] memory) {
        return splitPlans[_planId].rules;
    }

    function getExecution(bytes32 _executionId) external view returns (SplitExecution memory) {
        return executions[_executionId];
    }

    function getExecutionAllocations(bytes32 _executionId) external view returns (Allocation[] memory) {
        return executionAllocations[_executionId];
    }

    function getOwnerPlans(address _owner) external view returns (bytes32[] memory) {
        return ownerPlans[_owner];
    }

    function getAllPlanIds() external view returns (bytes32[] memory) {
        return allPlanIds;
    }

    function getPendingBalance(address _account) external view returns (uint256) {
        return pendingBalances[_account];
    }

    // ============ Pausable ============

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }
}

contracts/ERC8004SessionManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/security/Pausable.sol";

/**
 * @title ERC8004SessionManager
 * @dev ERC-8004 标准实现：Session Key 管理合约
 * 支持 Agent 自动化支付、高频小额支付场景
 */
contract ERC8004SessionManager is Ownable, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;
    using ECDSA for bytes32;

    struct Session {
        address signer;           // Session Key 地址
        address owner;            // 主钱包地址
        uint256 singleLimit;      // 单笔限额（USDC，6 decimals）
        uint256 dailyLimit;       // 每日限额（USDC，6 decimals）
        uint256 usedToday;        // 今日已用（USDC，6 decimals）
        uint256 expiry;           // 过期时间戳
        uint256 lastResetDate;    // 上次重置日期（用于每日限额重置）
        bool isActive;           // 是否激活
    }

    // 状态变量
    mapping(bytes32 => Session) public sessions;
    mapping(address => bytes32[]) public userSessions; // 用户的所有 Session
    address public usdcToken; // USDC 代币地址
    address public relayer;   // Relayer 地址

    // 事件
    event SessionCreated(
        bytes32 indexed sessionId,
        address indexed owner,
        address indexed signer,
        uint256 singleLimit,
        uint256 dailyLimit,
        uint256 expiry
    );

    event PaymentExecuted(
        bytes32 indexed sessionId,
        address indexed to,
        uint256 amount,
        bytes32 indexed paymentId
    );

    event SessionRevoked(
        bytes32 indexed sessionId,
        address indexed owner
    );

    event DailyLimitReset(
        bytes32 indexed sessionId,
        uint256 newDate
    );

    // 修饰符
    modifier onlyRelayer() {
        require(msg.sender == relayer, "Only relayer can execute");
        _;
    }

    modifier validSession(bytes32 sessionId) {
        Session storage session = sessions[sessionId];
        require(session.owner != address(0), "Session not found");
        require(session.isActive, "Session not active");
        require(block.timestamp <= session.expiry, "Session expired");
        _;
    }

    constructor(address _usdcToken) {
        require(_usdcToken != address(0), "Invalid USDC address");
        usdcToken = _usdcToken;
    }

    /**
     * @dev 创建 Session
     * @param signer Session Key 地址
     * @param singleLimit 单笔限额（USDC，6 decimals）
     * @param dailyLimit 每日限额（USDC，6 decimals）
     * @param expiry 过期时间戳
     */
    function createSession(
        address signer,
        uint256 singleLimit,
        uint256 dailyLimit,
        uint256 expiry
    ) external returns (bytes32 sessionId) {
        require(signer != address(0), "Invalid signer");
        require(singleLimit > 0, "Invalid single limit");
        require(dailyLimit >= singleLimit, "Daily limit must >= single limit");
        require(expiry > block.timestamp, "Invalid expiry");

        // 生成 Session ID
        sessionId = keccak256(
            abi.encodePacked(
                msg.sender,
                signer,
                block.timestamp,
                block.number,
                blockhash(block.number - 1)
            )
        );

        // 确保 Session ID 唯一
        require(sessions[sessionId].owner == address(0), "Session ID collision");

        // 创建 Session
        sessions[sessionId] = Session({
            signer: signer,
            owner: msg.sender,
            singleLimit: singleLimit,
            dailyLimit: dailyLimit,
            usedToday: 0,
            expiry: expiry,
            lastResetDate: block.timestamp / 1 days,
            isActive: true
        });

        // 记录用户 Session
        userSessions[msg.sender].push(sessionId);

        emit SessionCreated(
            sessionId,
            msg.sender,
            signer,
            singleLimit,
            dailyLimit,
            expiry
        );

        return sessionId;
    }

    /**
     * @dev 使用 Session 执行支付（由 Relayer 调用）
     * @param sessionId Session ID
     * @param to 收款地址
     * @param amount 支付金额（USDC，6 decimals）
     * @param paymentId 支付 ID（用于追踪）
     * @param signature Session Key 签名
     */
    function executeWithSession(
        bytes32 sessionId,
        address to,
        uint256 amount,
        bytes32 paymentId,
        bytes calldata signature
    ) external onlyRelayer validSession(sessionId) nonReentrant whenNotPaused {
        _executeWithSession(sessionId, to, amount, paymentId, signature);
    }

    /**
     * @dev 内部执行支付逻辑
     */
    function _executeWithSession(
        bytes32 sessionId,
        address to,
        uint256 amount,
        bytes32 paymentId,
        bytes calldata signature
    ) internal {
        Session storage session = sessions[sessionId];

        // 检查每日限额重置
        uint256 currentDate = block.timestamp / 1 days;
        if (currentDate > session.lastResetDate) {
            session.usedToday = 0;
            session.lastResetDate = currentDate;
            emit DailyLimitReset(sessionId, currentDate);
        }

        // 检查单笔限额
        require(amount <= session.singleLimit, "Exceeds single limit");

        // 检查每日限额
        require(
            session.usedToday + amount <= session.dailyLimit,
            "Exceeds daily limit"
        );

        // 验证签名（使用 OZ ECDSA 防止 s-value 可延展性攻击）
        bytes32 dataHash = keccak256(
            abi.encodePacked(
                sessionId,
                to,
                amount,
                paymentId,
                block.chainid
            )
        );
        bytes32 messageHash = dataHash.toEthSignedMessageHash();
        address recoveredSigner = messageHash.recover(signature);
        require(recoveredSigner == session.signer, "Invalid signature");

        // 更新已用额度
        session.usedToday += amount;

        // 从用户钱包转账 USDC 到收款地址
        // ⚠️ 重要：amount参数是6 decimals（用于签名验证和限额检查）
        // 但代币的实际精度可能是18 decimals（USDT），需要转换
        // 获取代币的实际精度
        uint8 tokenDecimals = IERC20Metadata(usdcToken).decimals();
        uint256 amountForTransfer = amount;
        
        // 如果代币精度不是6 decimals，需要转换
        if (tokenDecimals != 6) {
            if (tokenDecimals > 6) {
                // 从6 decimals转换为更高精度（例如：6 -> 18，乘以 10^12）
                uint256 scaleFactor = 10 ** (tokenDecimals - 6);
                amountForTransfer = amount * scaleFactor;
            } else {
                // 从6 decimals转换为更低精度（例如：6 -> 3，除以 10^3）
                uint256 scaleFactor = 10 ** (6 - tokenDecimals);
                amountForTransfer = amount / scaleFactor;
            }
        }
        
        IERC20(usdcToken).safeTransferFrom(
            session.owner,
            to,
            amountForTransfer
        );

        emit PaymentExecuted(sessionId, to, amount, paymentId);
    }

    /**
     * @dev 批量执行支付（节省 Gas）
     * @param sessionIds Session ID 数组
     * @param recipients 收款地址数组
     * @param amounts 支付金额数组
     * @param paymentIds 支付 ID 数组
     * @param signatures 签名数组
     */
    function executeBatchWithSession(
        bytes32[] calldata sessionIds,
        address[] calldata recipients,
        uint256[] calldata amounts,
        bytes32[] calldata paymentIds,
        bytes[] calldata signatures
    ) external onlyRelayer nonReentrant whenNotPaused {
        require(
            sessionIds.length == recipients.length &&
            recipients.length == amounts.length &&
            amounts.length == paymentIds.length &&
            paymentIds.length == signatures.length,
            "Array length mismatch"
        );
        require(sessionIds.length > 0 && sessionIds.length <= 50, "Invalid batch size");

        for (uint256 i = 0; i < sessionIds.length; i++) {
            // 首先验证 Session 有效性
            bytes32 sid = sessionIds[i];
            Session storage session = sessions[sid];
            require(session.owner != address(0), "Session not found");
            require(session.isActive, "Session not active");
            require(block.timestamp <= session.expiry, "Session expired");

            _executeWithSession(
                sid,
                recipients[i],
                amounts[i],
                paymentIds[i],
                signatures[i]
            );
        }
    }

    /**
     * @dev 撤销 Session
     * @param sessionId Session ID
     */
    function revokeSession(bytes32 sessionId) external {
        Session storage session = sessions[sessionId];
        require(session.owner == msg.sender, "Not session owner");
        require(session.isActive, "Session already revoked");

        session.isActive = false;

        emit SessionRevoked(sessionId, msg.sender);
    }

    /**
     * @dev 获取 Session 信息
     * @param sessionId Session ID
     */
    function getSession(bytes32 sessionId)
        external
        view
        returns (Session memory)
    {
        return sessions[sessionId];
    }

    /**
     * @dev 获取用户的所有 Session
     * @param user 用户地址
     */
    function getUserSessions(address user)
        external
        view
        returns (bytes32[] memory)
    {
        return userSessions[user];
    }

    /**
     * @dev 查询用户的代币授权状态
     * @param user 用户地址
     * @return allowance 授权额度
     * @return tokenAddress 代币地址
     * @return isAuthorized 是否已授权
     */
    function getUserTokenAllowance(address user)
        external
        view
        returns (
            uint256 allowance,
            address tokenAddress,
            bool isAuthorized
        )
    {
        tokenAddress = usdcToken;
        allowance = IERC20(usdcToken).allowance(user, address(this));
        isAuthorized = allowance > 0;
    }

    /**
     * @dev 设置 Relayer 地址
     */
    function setRelayer(address _relayer) external onlyOwner {
        require(_relayer != address(0), "Invalid relayer");
        relayer = _relayer;
    }

    /**
     * @dev 暂停合约
     */
    function pause() external onlyOwner {
        _pause();
    }

    /**
     * @dev 恢复合约
     */
    function unpause() external onlyOwner {
        _unpause();
    }
}

contracts/interfaces/IAgentPayment.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title IAgentPayment
 * @dev Agent 支付标准接口 - Agentrix EIP 草案
 * @notice 定义 AI Agent 生态系统中支付和分账的标准接口
 */
interface IAgentPayment {
    // ============ 数据结构 ============
    
    /**
     * @dev 支付意图结构
     */
    struct PaymentIntent {
        bytes32 intentId;           // 意图唯一标识
        address payer;              // 付款人
        address[] recipients;       // 收款人列表
        uint256[] amounts;          // 对应金额列表
        bytes32 collaborationId;    // 关联的协作协议ID
        uint256 totalAmount;        // 总金额
        uint256 createdAt;          // 创建时间
        uint256 expiresAt;          // 过期时间
        IntentStatus status;        // 状态
    }
    
    /**
     * @dev 分账配置结构
     */
    struct SplitConfig {
        address merchantWallet;     // 商户钱包
        uint256 merchantAmount;     // 商户金额
        address[] agents;           // Agent 地址列表
        uint256[] agentFees;        // Agent 费用列表
        uint256 platformFee;        // 平台费用
        bytes32 sessionId;          // Session ID
        bool isDisputed;            // 是否有争议
    }
    
    /**
     * @dev 意图状态枚举
     */
    enum IntentStatus {
        CREATED,        // 已创建
        APPROVED,       // 已批准
        EXECUTED,       // 已执行
        CANCELLED,      // 已取消
        EXPIRED,        // 已过期
        DISPUTED        // 争议中
    }

    // ============ 事件 ============
    
    /**
     * @dev 支付意图创建事件
     */
    event IntentCreated(
        bytes32 indexed intentId,
        address indexed payer,
        uint256 totalAmount,
        bytes32 collaborationId
    );
    
    /**
     * @dev 支付意图执行事件
     */
    event IntentExecuted(
        bytes32 indexed intentId,
        uint256 totalAmount,
        uint256 recipientCount
    );
    
    /**
     * @dev 支付意图取消事件
     */
    event IntentCancelled(
        bytes32 indexed intentId,
        address indexed canceller,
        string reason
    );
    
    /**
     * @dev 自动分账完成事件
     */
    event PaymentSplit(
        bytes32 indexed intentId,
        bytes32 indexed sessionId,
        address indexed merchantWallet,
        uint256 merchantAmount,
        uint256 agentFees,
        uint256 platformFee
    );

    // ============ 核心函数 ============
    
    /**
     * @dev 创建支付意图
     * @param recipients 收款人地址列表
     * @param amounts 对应金额列表
     * @param collaborationId 协作协议ID
     * @param expiresIn 有效期（秒）
     * @return intentId 创建的意图ID
     */
    function createIntent(
        address[] calldata recipients,
        uint256[] calldata amounts,
        bytes32 collaborationId,
        uint256 expiresIn
    ) external returns (bytes32 intentId);
    
    /**
     * @dev 执行支付意图
     * @param intentId 意图ID
     * @param proof 执行证明（如签名、Merkle proof等）
     */
    function executeIntent(
        bytes32 intentId,
        bytes calldata proof
    ) external;
    
    /**
     * @dev 取消支付意图
     * @param intentId 意图ID
     * @param reason 取消原因
     */
    function cancelIntent(
        bytes32 intentId,
        string calldata reason
    ) external;
    
    /**
     * @dev 设置分账配置
     * @param orderId 订单ID
     * @param config 分账配置
     */
    function setSplitConfig(
        bytes32 orderId,
        SplitConfig calldata config
    ) external;
    
    /**
     * @dev 执行自动分账
     * @param orderId 订单ID
     * @param amount 支付金额
     */
    function executeAutoSplit(
        bytes32 orderId,
        uint256 amount
    ) external;

    // ============ 查询函数 ============
    
    /**
     * @dev 获取支付意图详情
     */
    function getIntent(bytes32 intentId) external view returns (PaymentIntent memory);
    
    /**
     * @dev 获取分账配置
     */
    function getSplitConfig(bytes32 orderId) external view returns (SplitConfig memory);
    
    /**
     * @dev 获取待处理余额
     */
    function getPendingBalance(address payee, address token) external view returns (uint256);
}

